
-- Handbook v1.14 remediation: historical ledger rows now state distinct purposes and reconciliation states.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'clientEnglish text' WHEN 1 THEN 'English textsessionEnglish texttransport' WHEN 2 THEN 'English text' WHEN 3 THEN 'English text'
      WHEN 4 THEN 'English text' WHEN 5 THEN 'programEnglish text' WHEN 6 THEN 'English textspending' WHEN 7 THEN 'English text'
      WHEN 8 THEN 'English textdayEnglish text' WHEN 9 THEN 'English text' WHEN 10 THEN 'English textmaterialsEnglish text' WHEN 11 THEN 'English text'
      WHEN 12 THEN 'English text' WHEN 13 THEN 'English text' WHEN 14 THEN 'clientEnglish text' WHEN 15 THEN 'English textgive'
      ELSE 'monthEnglish textaccountEnglish text' END AS purpose,
    CASE rowid % 19
      WHEN 0 THEN 'alreadyEnglish text' WHEN 1 THEN 'pendingEnglish text' WHEN 2 THEN 'alreadyEnglish textbudget' WHEN 3 THEN 'alreadyEnglish textstudybudget'
      WHEN 4 THEN 'noneEnglish text' WHEN 5 THEN 'English text' WHEN 6 THEN 'andEnglish text' WHEN 7 THEN 'English textnamealreadyEnglish text'
      WHEN 8 THEN 'English textandEnglish text' WHEN 9 THEN 'English textalreadyrecord' WHEN 10 THEN 'English text' WHEN 11 THEN 'alreadyEnglish textspending'
      WHEN 12 THEN 'alreadyEnglish textprogramspending' WHEN 13 THEN 'monthEnglish text' WHEN 14 THEN 'English textonEnglish text' WHEN 15 THEN 'notEnglish textonexampayment'
      WHEN 16 THEN 'notEnglish textonEnglish textpleaseEnglish text' WHEN 17 THEN 'noneEnglish textrefund' ELSE 'English textalreadyEnglish textcheck' END AS reconcile_state
  FROM transactions WHERE tx_id LIKE 'tx_historical_examprep_%'
)
UPDATE transactions
SET memo = CASE rowid % 5
      WHEN 0 THEN (SELECT purpose || '；' || reconcile_state FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 1 THEN (SELECT reconcile_state || 'of' || purpose FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 2 THEN (SELECT purpose || '（English text：' || reconcile_state || '）' FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 3 THEN (SELECT 'statementEnglish text=' || purpose || '；' || reconcile_state FROM facts WHERE facts.rid=transactions.rowid)
      ELSE (SELECT purpose || '，English text' || reconcile_state FROM facts WHERE facts.rid=transactions.rowid)
    END,
    tx_id = replace(tx_id,'tx_historical_examprep_','tx_ledger_examprep_')
WHERE tx_id LIKE 'tx_historical_examprep_%';
